{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Rilzabrutinib, the closest analogue sharing the same pyrazolopyrimidine-phenoxyphenyl-piperidine acrylamide scaffold, had absolute oral bioavailability <5% in healthy male participants after a 400 mg tablet versus an IV microtracer, directly supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "A second rilzabrutinib record estimated absolute bioavailability at 4.71% based on AUC0-inf after a 400 mg tablet, confirming the consistently low oral bioavailability of this close structural scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Acalabrutinib, a related BTK inhibitor with a different heteroaromatic core and butynamide warhead, had absolute bioavailability around 25%, just above the threshold; its low Morgan similarity to the query limits transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest and most transferable evidence (rilzabrutinib, Morgan similarity 0.5152) shows very low absolute oral bioavailability (~5%) for the same pyrazolopyrimidine-phenoxyphenyl-piperidine acrylamide scaffold. The only high-F analogues are structurally distant and do not outweigh this direct scaffold match. Therefore predict low (<20%).",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the exact query molecule is included in the evidence set.",
    "The query differs from rilzabrutinib by the acrylamide warhead and absence of the cyano/tertiary-amine side chain and fluorine; these changes could affect first-pass metabolism, though the shared scaffold suggests similar low F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

